def mini_contains(hay, needle):
    # 生效条件：hay/needle 均为字符串
    # 子功能：① 空针返 True；② 滑动窗口逐位比对；③ 不命中返 False
    # 执行：循环迭代；条件分派
    # 不适用条件：正则/模糊匹配不在本单元范围；不用内建 in
    if not needle:
        return True
    if len(needle) > len(hay):
        return False
    for i in range(len(hay) - len(needle) + 1):
        ok = True
        for j in range(len(needle)):
            if hay[i + j] != needle[j]:
                ok = False
                break
        if ok:
            return True
    return False

task:去首尾空白.code:
def mini_strip(s):
    # 生效条件：s 为字符串
    # 子功能：① 定位首个非空白；② 定位末个非空白；③ 切片返回
    # 执行：顺序扫描；切片
    # 不适用条件：只去首尾，不去中间空白；不用内建 strip
    ws = ' \t\n\r'
    start = 0
    while start < len(s) and s[start] in ws:
        start += 1
    end = len(s)
    while end > start and s[end - 1] in ws:
        end -= 1
    return s[start:end]
